// The book with no daemon (ADR 0024): /preview.html?spread=open draws the main window's open book at
// its full window, ?spread=folded her window's folded one, both from spread/fixture.json (generated by
// scripts/spread_fixture.py through the daemon's own turn loop) and, for the chore page, the stage's
// staged draft. Signing and the look's switches answer here only; nothing reaches a daemon.

import { useState } from "react";
import { resetHer, useHer } from "../athena/store";
import type { Card, Draft, EngineStatus, HostReport, LedgerPage, ReportView, SpaceSummary, Turn } from "../lib/contract";
import { backPages } from "../main/athena/AthenaBook";
import { DepthFrame } from "../main/shell/Depth";
import { STAGED } from "../main/stage/fixture/staged";
import { useMain } from "../main/store";
import fixture from "../spread/fixture.json";
import { Spread } from "../spread/Spread";
import { Backdrop } from "../theme";
import "../athena/her.css";

interface Fixture {
  fixture: string;
  engine: EngineStatus;
  active: string;
  spaces: SpaceSummary[];
  turns: Turn[];
  cards: Card[];
  report: ReportView;
  elsewhere: HostReport;
  ledger: LedgerPage;
}

const F = fixture as Fixture;
/** A chore mid-sketch: the stage's staged draft after her second reply (pencil, ink and an open question). */
const DRAWING: Draft = STAGED.frames[1]?.draft ?? STAGED.created;

/** What show_report answered, from the fixture (one function, so the page reads it once). */
const readFixture = (): Promise<HostReport> => Promise.resolve(F.elsewhere);

function seed(): void {
  resetHer();
  useHer.setState({
    status: "ready",
    engine: F.engine,
    spaces: F.spaces,
    activeId: F.active,
    turns: F.turns,
    cards: Object.fromEntries(F.cards.map((c) => [c.id, c])),
  });
  useMain.setState({
    spaces: F.spaces,
    active: F.active,
    reports: { [F.active]: { load: "ready", view: F.report, problem: "", composing: false, composeProblem: "" } },
    ledger: F.ledger,
    engine: F.engine,
  });
}

function Invented() {
  return (
    <span className="badge" data-tone="warning" title={F.fixture}>
      Invented example
    </span>
  );
}

export function SpreadHarness({ layout }: { layout: "open" | "folded" | "shell" }) {
  const [ready] = useState(() => {
    seed();
    return true;
  });
  const [draft, setDraft] = useState<Draft>(DRAWING);
  if (!ready) return null;
  if (layout === "folded") {
    return (
      <main className="her-app coat">
        <Spread layout="folded" pill note={<Invented />} />
      </main>
    );
  }
  const back = backPages({
    spaceId: F.active,
    view: F.report,
    draft,
    setDraft,
    ledgerTotal: F.ledger.totals.cost_usd,
    readElsewhere: readFixture,
  });
  if (layout === "shell") {
    // as the main window draws it: under the shell's bar, beside its rail, no dock
    return (
      <DepthFrame route={{ view: "athena" }}>
        <Spread layout="open" back={back} note={<Invented />} />
      </DepthFrame>
    );
  }
  return (
    <div className="pv-spread">
      <Backdrop />
      <Spread layout="open" back={back} note={<Invented />} />
    </div>
  );
}
